const $ = s => document.querySelector(s);
const main = $('#main');
const escapeHTML = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved = {};
try { saved = JSON.parse(localStorage.getItem('sleepthrough-v3')||'{}') || {}; } catch {}
const state = {period:7,week:1,quizStep:0,answers:[],nightStep:0,lessonStep:0,lessonDay:8,plan:1,complete:Array.isArray(saved.complete)?saved.complete.filter(n=>Number.isInteger(n)&&n>=1&&n<=28):[1,2,3,4,5,6,7],notes:saved.notes||{},entry:saved.entry||null,lessonSteps:saved.lessonSteps||{}};
function persist(){try {localStorage.setItem('sleepthrough-v3',JSON.stringify({complete:state.complete,notes:state.notes,entry:state.entry,lessonSteps:state.lessonSteps}));}catch {toast('This browser could not save your progress. Keep this tab open.');}}
const currentDay=()=>lessons.find(l=>!state.complete.includes(l.day))?.day||28;
state.week=Math.floor((currentDay()-1)/7);
const icon = (name,cls='') => {const paths={moon:'M20.5 13A8.5 8.5 0 0 1 11 3.5 8.5 8.5 0 1 0 20.5 13Z',home:'m3 10 9-7 9 7v10H3Z M9 20v-7h6v7',book:'M3 4h6l3 2 3-2h6v16h-6l-3 2-3-2H3Z M12 6v16',chart:'M4 3v17h17 M8 15l4-5 4 2 5-8',journal:'M5 3h14v18H5Z M8 8h8 M8 12h8 M8 16h5',arrow:'M4 12h16 M14 6l6 6-6 6',check:'m5 12 4 4L19 6',sun:'M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z'};return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.moon}"/></svg>`;};
const btn=(label,href,cls='')=>`<a class="button ${cls}" href="${href}">${label}${icon('arrow')}</a>`;
const footer=()=>`<footer class="footer"><a class="brand" href="#home">☾ SleepThrough</a><p>More understanding. Less pressure.<br><small>Capstone product demo · No live accounts or payments.</small></p><a href="design-notes.html">Design & benchmarks ↗</a></footer>`;
const orb=(small=false)=>`<div class="orb-art ${small?'mini':''}" aria-hidden="true"><i></i><i></i><i></i><span>☾</span></div>`;
const timeline=()=>`<div class="timeline" role="img" aria-label="Illustrative sleep timeline: asleep, one brief waking around 3am, then asleep until morning."><i></i><i class="wake"></i><i></i></div><div class="timeline-labels"><span>10:45 pm</span><span class="lavender">Awake</span><span>6:30 am</span></div>`;
function chart(){const month=state.period===28, vals=month?[2.8,2.4,1.8,1.4]:[2,2,1,1,2,1,1],labels=month?['Week 1','Week 2','Week 3','Week 4']:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];return `<div class="bar-chart" role="img" aria-label="Example awakenings: ${vals.join(', ')}. ${month?'Weekly averages.':'Monday to Sunday.'}"><div class="chart-axis"><span>3</span><span>2</span><span>1</span><span>0</span></div>${vals.map((v,i)=>`<div class="bar-col"><div class="bar" style="--height:${v/3*100}%"><span>${v}</span></div><small>${labels[i]}</small></div>`).join('')}</div>`;}
function landing(){main.innerHTML=`
<section class="showcase-hero" id="home"><div class="showcase-copy"><span class="eyebrow"><i></i> BETTER NIGHTS, ONE SMALL STEP AT A TIME</span><h1>Awake at 3am?<br>Find your way<br>back to <em>rest.</em></h1><p>Discover why you wake in the middle of the night — and what to do next.</p><p class="showcase-detail">Your personal 28-day sleep reset. Short daily lessons, a step-by-step 3am protocol, and a clearer picture of your nights. Designed for life after 40.</p><div class="showcase-actions">${btn('Find my sleep plan','#quiz')}<a class="showcase-explore" href="#inside">Explore the app <span>↓</span></a></div><div class="showcase-notes"><span>${icon('check')} 12 questions · About 3 minutes</span><span>${icon('check')} No card to get your profile</span></div></div><div class="showcase-art"><div class="showcase-orbit" aria-hidden="true"></div><div class="showcase-orbit second" aria-hidden="true"></div><div class="showcase-moon" aria-hidden="true"></div><span class="showcase-star star-a" aria-hidden="true">✦</span><span class="showcase-star star-b" aria-hidden="true">✧</span><span class="showcase-star star-c" aria-hidden="true">✦</span><div class="showcase-hill hill-back" aria-hidden="true"></div><div class="showcase-hill hill-front" aria-hidden="true"></div><div class="showcase-hill hill-base" aria-hidden="true"></div><div class="showcase-phone" aria-label="SleepThrough mobile app preview with an illustrative waking profile"><div class="phone-island" aria-hidden="true"></div><div class="phone-status" aria-hidden="true"><span>7:30</span><span>▮▮ ▰</span></div><div class="showcase-phone-content"><span class="phone-greeting">YOUR PERSONAL SLEEP SPACE</span><h2>A little more<br>understanding.</h2><div class="phone-profile"><div class="phone-profile-icon">${icon('moon')}</div><span>YOUR 3AM PROFILE · EXAMPLE</span><h3>A busy mind<br>at night.</h3><p>A possible factor to explore.</p><div class="phone-factor"><i></i> Evening thoughts</div><div class="phone-factor"><i></i> Pressure around sleep</div></div><a class="phone-reset" href="#night-reset"><span>IF YOU WAKE TONIGHT</span><strong>Your 3am reset ${icon('arrow')}</strong><small>One quiet step at a time.</small></a><a class="phone-lesson" href="#lesson/8"><span>DAY 8 OF YOUR RESET</span><strong>Close the tabs in your mind.</strong><small>A short practice · 8 min →</small></a></div><div class="phone-bottom-nav" aria-hidden="true">${icon('home')}${icon('book')}${icon('moon')}${icon('chart')}</div></div><a class="showcase-float" href="#insights"><span>SMALL STEPS ADD UP.</span><h3>Your nights,<br>in perspective.</h3><p><strong>1.4</strong> awakenings / night</p><div class="showcase-bars" aria-hidden="true">${[68,68,36,36,68,36,36].map((h,i)=>`<i style="height:${h}%" class="bar-${i}"></i>`).join('')}</div><small>Illustrative weekly average</small></a><span class="showcase-art-note">A LOOK INSIDE · ILLUSTRATIVE PROFILE & DATA</span></div></section>
<div class="promise-bar"><span>${icon('moon')} A protocol for tonight</span><span>${icon('book')} A 28-day path</span><span>${icon('chart')} Progress beyond a score</span></div>
<section class="section recognition"><span class="eyebrow">IT’S THE PART OF THE NIGHT NO ONE PLANS FOR.</span><h2>Fine at bedtime.<br>Wide awake a few hours later.</h2><div class="recognition-grid"><article><span>01 / THE WAKE-UP</span><h3>“Why am I awake again?”</h3><p>You check the time. Start counting the hours left. Suddenly sleep feels like a deadline.</p></article><article><span>02 / THE MENTAL TABS</span><h3>“I’ll just think this through.”</h3><p>One thought turns into tomorrow’s meeting, that conversation, and everything you didn’t finish.</p></article><article><span>03 / THE NEXT MORNING</span><h3>“How do I get through today?”</h3><p>You want more than another number. You want to understand the pattern and know where to begin.</p></article></div><div class="recognition-close">Start with your waking pattern.<br><strong>Give the next night a clearer plan.</strong></div></section>
<section class="section how-v4" id="how"><div class="section-head"><div><span class="eyebrow">A PLAN FOR THE MOMENT. A PATH FOR THE MONTH.</span><h2>Know your next step.<br>Even at 3am.</h2></div><p>Three small pieces that work together — before bed, during the night, and the next morning.</p></div><div class="steps"><article><span class="num">01</span><h3>Find your possible factors</h3><p>Explore your waking, evening thoughts, routine, and sleep space. Get a profile that explains why a particular practice may fit you.</p><a href="#quiz">Find my pattern ↗</a></article><article><span class="num">02</span><h3>Have a plan when you wake</h3><p>A quiet, three-step protocol you can explore before bed and return to at night. No timer to beat. One calm action at a time.</p><a href="#night-reset">Try tonight’s reset ↗</a></article><article><span class="num">03</span><h3>Practice one small skill a day</h3><p>Follow a 28-day learning path, keep a simple morning diary, and notice your awakenings over time.</p><a href="#lessons">See my learning path ↗</a></article></div></section>
<section class="section offer-v4"><div><span class="eyebrow">WHAT YOU GET AFTER THE QUIZ</span><h2>A starting point<br>that makes sense <em>for you.</em></h2><p>Your answers shape the profile and first practice. You can explore the result before choosing a plan.</p>${btn('Get my free sleep profile','#quiz')}<small>No email or payment details needed for your profile.</small></div><div class="profile-demo"><div class="card-top"><span>EXAMPLE PROFILE</span>${icon('spark')}</div><h3>The midnight<br>overthinker.</h3><p>Thoughts feel louder when the house gets quiet.</p><div class="profile-demo-factor"><span>YOU MIGHT RECOGNIZE</span><strong>Evening thoughts + pressure to sleep</strong></div><div class="profile-demo-factor"><span>YOUR FIRST PRACTICE</span><strong>A thought download before bed</strong><small>Day 8 · 8 minutes</small></div><div class="profile-demo-footer">Based on your answers. A possibility to explore, not a diagnosis.</div></div></section>
<section class="section program-section" id="program"><div class="program-intro"><span class="eyebrow">YOUR 28-DAY SLEEP RESET</span><h2>One small lesson.<br>One less thing<br>to figure out.</h2><p>Short explanations, real-life practices, and room to reflect. Move along a clear path, revisit what helps, and pick up wherever you left off.</p>${btn('Explore the learning path','#lessons','outline')}<span class="quiet-note">About 5–10 minutes a day · Designed for life after 40</span></div><div class="mini-path" aria-label="Four weeks: notice, unwind, repeat, continue">${weeks.map((w,i)=>`<a href="#lessons" class="mini-path-stop"><span>${i===0?'✓':i===1?'★':i+1}</span><div><small>WEEK ${i+1} · ${w.label}</small><h3>${w.title}</h3></div></a>`).join('')}</div></section>
<section class="section inside" id="inside"><div class="preview-card"><div class="card-top"><span>${icon('moon')} YOUR NIGHTS, AT A GLANCE</span><span>EXAMPLE</span></div><div class="preview-number">1.4 <span>/ night</span></div><h3>Your awakenings.<br>The bigger picture.</h3><p>Illustrative weekly average</p>${timeline()}<div class="metric-pair"><span>22 min <small>awake at night</small></span><span>7h 12m <small>time asleep</small></span></div></div><div class="inside-copy"><span class="eyebrow">LESS GUESSING. MORE UNDERSTANDING.</span><h2>See what changes.<br>Beyond a sleep score.</h2><p>Follow how often you wake, how long you feel awake, and what you’re practicing. Look at the week, with room for the nights that feel different.</p><ul class="plain-list"><li>${icon('check')} A one-minute morning check-in</li><li>${icon('check')} Weekly and monthly perspectives</li><li>${icon('check')} Your notes alongside your learning</li></ul>${btn('Preview my sleep space','#dashboard','outline')}</div></section>
<section class="approach-v4"><span class="eyebrow">CLEAR ABOUT THE APPROACH</span><h2>Practical skills.<br>Human expectations.</h2><div><p>Explore the thoughts, habits, and routines around your nights through everyday learning inspired by cognitive and behavioral sleep skills.</p><p>This is a self-guided wellness prototype. It does not diagnose the cause of insomnia or replace professional care. The 28 days describe the program, not a promised recovery time.</p></div></section>
<section class="section faq-section" id="faq"><div><span class="eyebrow">BEFORE YOU GET STARTED</span><h2>A few things<br>worth knowing.</h2></div><div class="faqs">${[['What will the quiz tell me?','You will get a profile of possible factors, a summary of the answers behind it, and a suggested first practice. It takes about three minutes and does not diagnose a medical cause.'],['How is this different from tracking sleep?','The diary helps you notice change, while the learning path and 3am protocol give you something practical to try. You do not need a watch or a ring to explore the program.'],['What does 28 days mean?','Four weeks of short lessons and practices. Most take 5–10 minutes. It is a learning structure, not a guarantee about when your sleep will change.'],['Do I have to complete a lesson every day?','No. Your progress stays saved in this browser. Return at your own pace, revisit a lesson, or simply use the night reset when you need it.'],['Is my profile free?','Yes. You can explore the quiz result without an email or payment. This capstone prototype has no live subscriptions or app-store downloads.'],['What if my sleep problems continue?','A self-guided program has limits. If sleep difficulties persist or affect your daily life, discuss them with a qualified healthcare professional.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section>
<section class="final-cta"><span class="eyebrow">YOUR NEXT NIGHT DESERVES A CLEARER PLAN.</span><h2>Let’s close<br>a few tabs.</h2><p>Start with what’s happening at 3am.<br>Find one small thing to try next.</p>${btn('Find my 3am pattern','#quiz')}<small>12 questions · About 3 minutes · Free profile</small></section>${footer()}`;}
function appShell(active,body){main.innerHTML=`<div class="app-layout"><aside class="sidebar"><div class="sidebar-label">YOUR SLEEP SPACE</div><nav aria-label="Sleep space">${[['dashboard','home','Today'],['lessons','book','My 28-day reset'],['insights','chart','Sleep insights'],['journal','journal','My journal']].map(([r,i,t])=>`<a class="${active===r?'active':''}" href="#${r}" ${active===r?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('')}</nav><a class="sidebar-night" href="#night-reset">${icon('moon')}<strong>Awake at 3am?</strong><span>Your quiet reset →</span></a><div class="sidebar-bottom"><span class="avatar">A</span><div>Alex’s space<small>Demo account</small></div></div></aside><div class="app-content">${body}<p class="app-footnote">Interactive product demo · Sample sleep data · Progress saved in this browser</p></div></div>`;}
const pageHead=(tag,title,action='')=>`<div class="page-head"><div><span class="eyebrow">${tag}</span><h1>${title}</h1></div>${action}</div>`;
function sleepCard(){const e=state.entry;return `<article class="card sleep-card"><div class="card-top"><span>${icon('moon')} ${e?'YOUR LATEST CHECK-IN':'LAST NIGHT · SAMPLE DATA'}</span><button class="icon-button" data-action="checkin" aria-label="Edit morning check-in">↗</button></div><div class="sleep-main"><strong>${e?escapeHTML(e.wakes):1}</strong><div><span>awakening${e&&Number(e.wakes)!==1?'s':''}</span><small>${e?'Recorded by you':'Your main measure of progress'}</small></div></div><h2>${e?'Thanks for checking in.':'A little more uninterrupted rest.'}</h2>${e?'<p class="muted">Your own estimate · The weekly chart below remains an example.</p>':timeline()}<div class="metric-pair"><span>${e?escapeHTML(e.awake):18} min<small>awake during the night</small></span><span>${e?escapeHTML(e.hours)+' h':'7h 24m'}<small>time asleep</small></span></div></article>`;}
function today(){const d=currentDay(),l=lessons[d-1];appShell('dashboard',`${pageHead('YOUR NEXT SMALL STEP','Good morning, Alex.',`<button class="button outline small" data-action="checkin">${icon('sun')} Morning check-in</button>`)}<div class="dashboard-grid">${sleepCard()}<article class="card daily-card"><div class="card-top"><span>TODAY’S LESSON</span><span>DAY ${d} / 28</span></div>${orb(true)}<span class="eyebrow">WEEK ${l.week+1} · ${weeks[l.week].label}</span><h2>${l.title}</h2><p>${l.minutes} min · A little understanding. One small practice.</p>${btn('Start today’s lesson',`#lesson/${d}`)}</article></div><div class="dashboard-lower"><article class="card"><div class="card-top"><div><span class="eyebrow">THE BIGGER PICTURE</span><h3>Your awakenings</h3></div><div class="segmented"><button data-period="7" aria-pressed="${state.period===7}">Week</button><button data-period="28" aria-pressed="${state.period===28}">Month</button></div></div><div class="chart-summary"><strong>${state.period===7?'1.4':'2.1'} <small>/ night</small></strong><span>Example ${state.period===7?'week':'month'}</span></div>${chart()}<a class="text-link" href="#insights">Explore your sleep insights ↗</a></article><article class="card profile-card"><span class="eyebrow">YOUR 3AM PROFILE · EXAMPLE</span>${icon('spark')}<h2>A busy mind<br>at night.</h2><p>Evening thoughts may be part of your waking pattern. This week, try giving them a place to land.</p><a class="text-link" href="#lesson/8">Practice a thought download ↗</a><small>Possible factor, not a diagnosis.</small></article></div>`);}
function lessonList(){const w=state.week,done=state.complete.length,weekDone=state.complete.filter(d=>Math.floor((d-1)/7)===w).length;appShell('lessons',`${pageHead('YOUR 28-DAY SLEEP JOURNEY','A little practice. A quieter path.')}<div class="learning-stats"><span>${icon('spark')} <strong>${done*10}</strong> learning points</span><span>${icon('check')} <strong>${done}</strong> lessons explored</span><span>${icon('moon')} Your own pace</span></div><div class="week-tabs" role="tablist" aria-label="Program week">${weeks.map((x,i)=>`<button role="tab" aria-selected="${w===i}" data-week="${i}"><span>WEEK 0${i+1}</span>${x.label}</button>`).join('')}</div><div class="path-layout"><section class="learning-path-panel"><div class="unit-banner unit-${w}"><span class="eyebrow">WEEK ${w+1} · ${weeks[w].label}</span><h2>${weeks[w].title}</h2><p>${weeks[w].subtitle}</p><div class="unit-progress"><i style="width:${weekDone/7*100}%"></i></div><small>${weekDone} of 7 lessons complete</small></div><div class="learning-path">${lessons.filter(l=>l.week===w).map((l,i)=>{const isDone=state.complete.includes(l.day),cur=l.day===currentDay(),offset=[0,-60,-85,-35,45,65,10][i];return `<div class="path-row ${isDone?'done':''} ${cur?'current':''}" style="--offset:${offset}px">${cur?'<span class="start-label">YOUR NEXT STEP</span>':''}<a href="#lesson/${l.day}" class="path-node ${isDone?'done':cur?'current':'future'}" aria-label="Day ${l.day}: ${l.title}. ${isDone?'Completed, revisit':cur?'Next lesson':'Preview lesson'}">${isDone?icon('check'):icon(i===6?'spark':i%3===0?'book':i%3===1?'moon':'sun')}</a><div class="path-title"><span>DAY ${l.day} · ${l.minutes} MIN</span><h3>${l.title}</h3><small>${isDone?'✓ In your toolkit':cur?'Start this lesson →':'Preview at your pace'}</small></div></div>`;}).join('')}<div class="week-reward ${weekDone===7?'earned':''}"><span>${weekDone===7?'✦':'☆'}</span><strong>${weekDone===7?'A week in your toolkit.':'Your weekly reflection awaits.'}</strong><p>${weekDone===7?'Return to any practice whenever it helps.':'Seven small steps. One moment to look back.'}</p>${weekDone===7&&w<3?`<button class="button small" data-week="${w+1}">Explore week ${w+2} ${icon('arrow')}</button>`:''}</div></div></section><aside class="path-companion"><div class="companion-art">${orb(true)}</div><h3>Small steps<br>still count.</h3><p>These points celebrate learning. They don’t measure your sleep or your worth.</p><div class="companion-next"><span class="eyebrow">PICK UP WHERE YOU LEFT OFF</span><strong>Day ${currentDay()} · ${lessons[currentDay()-1].title}</strong>${btn('Continue my journey',`#lesson/${currentDay()}`,'small')}</div><a class="text-link" href="#night-reset">Need support tonight? →</a></aside></div><div class="gentle-note">${icon('moon')}<p>No lost streaks. No penalties. Your place is saved, and every lesson stays available to preview.</p></div>`);}
function lesson(day){const l=lessons[day-1];state.lessonDay=day;const step=state.lessonStep;appShell('lessons',`<div class="lesson-reader"><a class="text-link" href="#lessons">← Your 28-day reset</a><div class="reader-top"><span class="eyebrow">DAY ${day} · ${l.minutes} MIN · WEEK ${l.week+1}</span><span>${state.complete.includes(day)?'✓ Completed':'Your pace. Your space.'}</span></div><div class="reader-progress" aria-label="Step ${step+1} of 3">${['Understand','Try it','Reflect'].map((s,i)=>`<button data-lesson-step="${i}" class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}><span>${i+1}</span>${s}</button>`).join('')}</div><article class="reader-card"><div class="reader-art art-${day%4}">${orb(true)}</div><span class="eyebrow">${['A LITTLE UNDERSTANDING','ONE SMALL PRACTICE','A MOMENT FOR YOU'][step]}</span><h1>${l.title}</h1><p class="reader-text">${step===0?l.learn:step===1?l.practice:'There is no right answer. A few words are enough, or simply take a moment to think.'}</p>${step===1?`<div class="practice-note">${icon('moon')} Try this when it feels comfortable. You can pause and come back.</div>`:''}${step===2?`<label class="reflection-label" for="reflection">${l.question}</label><textarea id="reflection" rows="4" maxlength="1500" placeholder="A thought to come back to…">${escapeHTML(state.notes[day]||'')}</textarea><small class="muted">Optional · Saved in this browser only</small>`:''}<div class="reader-actions">${step>0?`<button class="text-button" data-lesson-step="${step-1}">← Back</button>`:'<span></span>'}${step<2?`<button class="button" data-lesson-step="${step+1}">${step===0?'Try the practice':'Take a moment to reflect'} ${icon('arrow')}</button>`:`<button class="button" data-action="complete">${state.complete.includes(day)?'Save reflection':'Complete lesson'} ${icon('check')}</button>`}</div></article><p class="reader-help">Educational wellness content · No pressure to make sleep happen.</p></div>`);}
function completion(){const l=lessons[state.lessonDay-1],next=Math.min(28,state.lessonDay+1);appShell('lessons',`<div class="completion playful-completion"><div class="celebration-stars" aria-hidden="true">✦ <span>✧</span> ✦</div><div class="complete-icon">${icon('check')}</div><span class="eyebrow">DAY ${state.lessonDay} · IN YOUR TOOLKIT</span><h1>One small step.<br>Something to keep.</h1><p>“${l.title}”<br>You made a little space for yourself.</p><div class="achievement-row"><span>${icon('spark')}<strong>10</strong><small>points per lesson</small></span><span>${icon('book')}<strong>${state.complete.length}</strong><small>lessons complete</small></span></div><div class="stack-actions">${btn('Back to my path','#lessons')}${state.lessonDay<28?btn(`Preview day ${next}`,`#lesson/${next}`,'outline'):btn('See my sleep insights','#insights','outline')}</div><small class="completion-note">Learning progress, at your pace. Sleep is never a competition.</small></div>`);}
function insights(){appShell('insights',`${pageHead('UNDERSTAND YOUR NIGHTS','Look for a pattern, not perfection.')}<div class="card insights-main"><div class="card-top"><span class="eyebrow">AWAKENINGS PER NIGHT · SAMPLE DATA</span><div class="segmented"><button data-period="7" aria-pressed="${state.period===7}">7 days</button><button data-period="28" aria-pressed="${state.period===28}">28 days</button></div></div><div class="insight-number">${state.period===7?'1.4':'2.1'}<small>/ night</small></div><div class="trend">↓ ${state.period===7?'0.8':'0.5'} compared with the previous ${state.period===7?'week':'28 days'}</div>${chart()}<p class="muted">Illustrative ${state.period===7?'daily values: 2, 2, 1, 1, 2, 1, 1':'weekly averages: 2.8, 2.4, 1.8, 1.4'}. This chart is a product example, not your recorded data.</p></div><div class="stat-grid"><article class="card"><span class="eyebrow">TIME AWAKE</span><strong>${state.period===7?'22':'31'} <small>min / night</small></strong><p>The time between waking and settling back.</p></article><article class="card"><span class="eyebrow">TIME ASLEEP</span><strong>${state.period===7?'7h 12m':'6h 48m'}</strong><p>One part of the picture, alongside how you feel.</p></article><article class="card"><span class="eyebrow">LESSON PROGRESS · DEMO</span><strong>${state.complete.length}<small> / 28</small></strong><p>Learning and practice, at your own pace.</p></article></div><div class="gentle-note">${icon('spark')}<p><strong>A pattern to explore</strong><br>Notice awakenings alongside your evening notes. A connection is a useful question, not proof of a cause.</p></div>`);}
function journal(){const e=state.entry,notes=Object.entries(state.notes).filter(([,t])=>t.trim());appShell('journal',`${pageHead('A PLACE TO NOTICE','Your nights, in your words.',`<button class="button small" data-action="checkin">Add a check-in ${icon('arrow')}</button>`)}<article class="card journal-card"><span class="eyebrow">${e?'YOUR LATEST CHECK-IN':'MORNING CHECK-IN'}</span><h2>${e?'One night in your bigger picture.':'Start with a small observation.'}</h2>${e?`<div class="stat-grid compact"><div><strong>${escapeHTML(e.wakes)}</strong><span>awakenings</span></div><div><strong>${escapeHTML(e.awake)} min</strong><span>awake at night</span></div><div><strong>${escapeHTML(e.hours)} h</strong><span>asleep</span></div></div><p>${escapeHTML(e.rested)} · ${escapeHTML(new Date(e.date).toLocaleDateString('en-GB',{day:'numeric',month:'long'}))}</p>`:'<p>An estimate is enough. Take a minute in the morning to note how the night felt.</p>'}<button class="text-button" data-action="checkin">${e?'Edit this check-in':'Record my night'} ↗</button></article><h2 class="journal-heading">Lesson reflections <span>${notes.length}</span></h2>${notes.length?notes.map(([day,t])=>`<article class="card reflection-card"><span class="eyebrow">DAY ${day} · ${lessons[day-1]?.title||'Reflection'}</span><p>${escapeHTML(t)}</p><a class="text-link" href="#lesson/${day}">Revisit lesson ↗</a></article>`).join(''):'<div class="empty-state">'+icon('journal')+'<h3>A little room for your thoughts.</h3><p>Your saved lesson reflections will appear here.</p>'+btn('Explore the lessons','#lessons','outline')+'</div>'}<div class="data-note"><p>These notes stay in this browser. Demo data does not sync between devices.</p><button class="text-button" data-action="clear">Clear my demo data</button></div>`);}
const quizQuestions=[
 {group:'YOUR NIGHTS',title:'What would you most like to change?',sub:'Choose the improvement that would matter most in your everyday life.',options:['Wake less often at night','Get back to sleep more easily','Quiet my mind at night','Feel more rested in the morning']},
 {group:'YOUR NIGHTS',title:'How long has this been on your mind?',sub:'Think about the sleep pattern that brought you here.',options:['Less than two weeks','Two weeks to three months','Three months to a year','More than a year']},
 {group:'YOUR NIGHTS',title:'How many nights do you usually wake?',sub:'Think about a typical week. Your best estimate is enough.',options:['One night or less','Two or three nights','Four or five nights','Six or seven nights']},
 {group:'YOUR NIGHTS',title:'When do you tend to wake?',sub:'You do not need exact clock times.',options:['Soon after I fall asleep','In the middle of the night, often around 3am','Earlier than I want to get up','It changes from night to night']},
 {group:'YOUR NIGHTS',title:'How long do you feel awake?',sub:'Estimate from memory — no need to time yourself tonight.',options:['Usually just a few minutes','Around 15–30 minutes','Around 30–60 minutes','Often more than an hour']},
 {group:'YOUR MIND',title:'What tends to happen when you wake?',sub:'Choose what feels most familiar.',options:['Thoughts and tomorrow’s to-do list take over','I worry about not getting enough sleep','Light, sound, temperature, or comfort distracts me','I feel awake, but I’m not sure why']},
 {group:'YOUR MIND',title:'How often does your mind feel busy before bed?',sub:'Think about the last two weeks.',options:['Rarely','Sometimes','Often','Almost every night']},
 {group:'YOUR MIND',title:'What do you usually do after waking?',sub:'There is no right answer. We are looking for a starting point.',options:['Check the time and count the hours left','Open my phone, messages, or work','Lie quietly or choose a quiet activity','It varies — I do not have a familiar next step']},
 {group:'YOUR RHYTHM',title:'How predictable is your sleep routine?',sub:'Consider both bedtime and getting up.',options:['Quite consistent most days','It shifts by an hour or so','Weekdays and weekends feel very different','It changes a lot because of work or responsibilities']},
 {group:'YOUR RHYTHM',title:'What do your last 30 minutes before bed look like?',sub:'Pick the one closest to your usual evening.',options:['Work, planning, or catching up on tasks','Scrolling or watching something on a screen','A quiet, familiar wind-down','Different every evening']},
 {group:'YOUR NEXT STEP',title:'What feels hardest the next day?',sub:'Your daytime experience matters too.',options:['Focusing or getting things done','Feeling emotionally steady','Having energy for things I enjoy','It changes — I’m still noticing']},
 {group:'YOUR NEXT STEP',title:'What would make a plan easier to follow?',sub:'We’ll use this to suggest how to begin.',options:['A short evening practice','A clear next step when I wake','A simple morning check-in','A flexible lesson I can return to']}
];
function quiz(){const q=quizQuestions[state.quizStep],stage=['YOUR NIGHTS','YOUR MIND','YOUR RHYTHM','YOUR NEXT STEP'].indexOf(q.group);main.innerHTML=`<div class="quiz-page detailed-quiz"><div class="quiz-top"><a href="#home" class="text-link">← SleepThrough</a><span>QUESTION ${state.quizStep+1} / ${quizQuestions.length}</span></div><div class="quiz-stages">${['Your nights','Your mind','Your rhythm','Your next step'].map((s,i)=>`<span class="${i===stage?'active':i<stage?'done':''}">${i<stage?'✓':String(i+1).padStart(2,'0')} ${s}</span>`).join('')}</div><div class="quiz-progress"><i style="width:${(state.quizStep+1)/quizQuestions.length*100}%"></i></div><div class="quiz-layout"><div><span class="eyebrow">${q.group}</span><h1>${q.title}</h1><p>${q.sub}</p><div class="quiz-options" role="group" aria-label="Answer options">${q.options.map((a,i)=>`<button data-answer="${i}" aria-pressed="${state.answers[state.quizStep]===i}"><span>${String.fromCharCode(65+i)}</span>${a}<i>${state.answers[state.quizStep]===i?'✓':'○'}</i></button>`).join('')}</div><div class="quiz-actions"><button class="text-button" data-action="quiz-back" ${state.quizStep===0?'disabled':''}>← Back</button><button class="button" data-action="quiz-next" ${state.answers[state.quizStep]===undefined?'disabled':''}>${state.quizStep===quizQuestions.length-1?'See my profile':'Continue'} ${icon('arrow')}</button></div></div><aside class="quiz-aside">${orb()}<span class="eyebrow">WHAT YOU’LL LEAVE WITH</span><h2>A little understanding.<br>A practical next step.</h2><ul><li>Possible factors behind your waking</li><li>The answers behind your profile</li><li>A first lesson that fits your pattern</li><li>Your protocol for an awake moment</li></ul><small>A reflection tool, not a clinical assessment. No email needed for your result.</small></aside></div></div>${footer()}`;}
function result(){const p=getSleepProfile();main.innerHTML=`<div class="result-page detailed-result"><span class="eyebrow">YOUR 3AM PROFILE · BASED ON YOUR ANSWERS</span><h1>Here’s your starting point.</h1><p class="result-goal">Your goal: ${escapeHTML(p.goal.toLowerCase())}.</p><div class="result-card"><div class="result-art">${orb()}<span>ONE PATTERN TO EXPLORE</span></div><div><span class="eyebrow">${escapeHTML(p.factor)}</span><h2>${p.name}.</h2><p>${p.why}</p><div class="evidence-list"><small>WHAT YOU TOLD US</small>${p.evidence.map(t=>`<p>${icon('check')}${t}</p>`).join('')}</div>${p.secondary?`<div class="secondary-factor">Also worth noticing: <strong>${p.secondary.toLowerCase()}</strong></div>`:''}<div class="recommended"><small>YOUR SUGGESTED FIRST LESSON · DAY ${p.day}</small><strong>${p.practice}</strong><a href="#lesson/${p.day}">Try this practice ↗</a></div>${btn('Explore my 28-day plan','#plans')}</div></div><div class="result-next-grid"><article><span class="eyebrow">IF YOU WAKE TONIGHT</span><h3>Have your next step ready.</h3><p>Explore the three-step protocol before bed, then return to it if you need to.</p><a class="text-link" href="#night-reset">Open the 3am reset →</a></article><article><span class="eyebrow">A FORMAT THAT FITS YOU</span><h3>${escapeHTML(p.format)}.</h3><p>Start small. Your full learning path stays available to explore at your own pace.</p><a class="text-link" href="#lessons">See my learning path →</a></article></div>${p.longTerm?'<div class="support-result">You mentioned this has been happening for at least three months. If sleep is affecting your daily life, consider discussing it with a qualified healthcare professional alongside exploring these practices.</div>':''}<p class="muted">This profile uses simple rules across your answers. It suggests possible factors; it cannot establish a cause or diagnose insomnia.</p><button class="text-button" data-action="retake">Review my answers / retake quiz</button></div>${footer()}`;}
function plans(){main.innerHTML=`<div class="plans-page"><span class="eyebrow">YOUR PLAN, AT YOUR PACE</span><h1>A clearer next step.<br>A little support each day.</h1><p>Every option includes the 28-day reset, your journal, and your 3am protocol.</p><div class="pricing-grid">${[['1 month','$16.99','Then $29.99 / month'],['3 months','$27.99','Then $49.99 / 3 months'],['6 months','$39.99','Then $69.99 / 6 months']].map((p,i)=>`<button class="pricing-card ${state.plan===i?'selected':''}" data-plan="${i}" aria-pressed="${state.plan===i}"><span>${p[0]} ${i===1?'· MORE TIME TO PRACTICE':''}</span><strong>${p[1]}</strong><small>Introductory total · ${p[0]}</small><p>${p[2]}</p><span>${state.plan===i?'✓ Selected':'Select plan'}</span></button>`).join('')}</div><p class="muted">Pricing concepts for research. No subscription or payment will be created.</p>${btn('Preview my sleep space','#dashboard')}<a class="text-link" href="#profile">← Back to my profile</a></div>${footer()}`;}
const nightSteps=[['You’re awake.<br>Let’s make a little space.','You do not need to solve the night. Let your shoulders soften if that feels comfortable. Breathe naturally.','Settle into this moment'],['Those thoughts<br>can wait a little.','If something is looping, gently name it: “a thought about tomorrow.” You can return to it in the daytime. There is nothing to finish right now.','Let the thought pass'],['Choose a quiet<br>next step.','If you feel sleepy, let yourself rest. If you feel wide awake and frustrated, consider a quiet activity in dim light, returning to bed when you feel sleepy.','Finish my quiet reset']];
function night(){const n=nightSteps[state.nightStep];main.innerHTML=`<section class="night-page"><a class="text-link" href="#dashboard">← My sleep space</a><span class="eyebrow">YOUR 3AM PROTOCOL · STEP ${state.nightStep+1} OF 3</span>${orb()}<h1>${n[0]}</h1><p>${n[1]}</p><div class="night-dots">${nightSteps.map((_,i)=>`<span class="${i===state.nightStep?'active':''}"></span>`).join('')}</div><button class="button light" data-action="night-next">${n[2]} ${icon('arrow')}</button>${state.nightStep>0?'<button class="text-button" data-action="night-back">← Previous step</button>':''}<small>No countdown. No performance. Move on when you’re ready.</small></section>`;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function saveReflection(){const el=$('#reflection');if(el){state.notes[state.lessonDay]=el.value;persist();}}
function render(){const hash=location.hash.slice(1)||'home',isApp=['dashboard','lessons','insights','journal','complete'].includes(hash)||hash.startsWith('lesson/');document.body.classList.toggle('app-mode',isApp);document.body.classList.toggle('night-mode',hash==='night-reset');if(hash.startsWith('lesson/')){const d=Number(hash.split('/')[1]);if(Number.isInteger(d)&&d>=1&&d<=28){state.lessonStep=Number(state.lessonSteps[d])||0;lesson(d);}else{location.hash='lessons';return;}}else{const routes={dashboard:today,lessons:lessonList,insights,journal,complete:completion,quiz,profile:result,plans,'night-reset':night,ritual:night};(routes[hash]||landing)();}window.scrollTo(0,0);if(['how','program','faq','inside','progress'].includes(hash))requestAnimationFrame(()=>document.getElementById(hash)?.scrollIntoView({behavior:'smooth'}));document.title=`SleepThrough — ${isApp?'Your sleep space':'Close the tabs. Find your rest.'}`;}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.period){state.period=Number(t.dataset.period);location.hash==='#insights'?insights():today();}if(t.dataset.week!==undefined){state.week=Number(t.dataset.week);lessonList();}if(t.dataset.lessonStep!==undefined){saveReflection();state.lessonStep=Number(t.dataset.lessonStep);state.lessonSteps[state.lessonDay]=state.lessonStep;persist();lesson(state.lessonDay);}if(t.dataset.answer!==undefined){state.answers[state.quizStep]=Number(t.dataset.answer);quiz();}if(t.dataset.plan!==undefined){state.plan=Number(t.dataset.plan);plans();}switch(t.dataset.action){case 'checkin':{const f=$('#checkin-form');if(state.entry)for(const k of ['wakes','awake','hours','rested'])f.elements[k].value=state.entry[k];$('#checkin').showModal();break;}case 'complete':saveReflection();if(!state.complete.includes(state.lessonDay))state.complete.push(state.lessonDay);persist();state.week=Math.floor((currentDay()-1)/7);location.hash='complete';break;case 'quiz-next':if(state.answers[state.quizStep]===undefined)return;if(state.quizStep<quizQuestions.length-1){state.quizStep++;quiz();}else location.hash='profile';break;case 'quiz-back':if(state.quizStep>0){state.quizStep--;quiz();}break;case 'retake':state.quizStep=0;state.answers=[];location.hash='quiz';break;case 'night-next':if(state.nightStep<2){state.nightStep++;night();}else{state.nightStep=0;location.hash='dashboard';toast('Your quiet reset is complete. Take the next step at your own pace.');}break;case 'night-back':state.nightStep=Math.max(0,state.nightStep-1);night();break;case 'clear':if(confirm('Clear saved check-ins and reflections, and restart your lesson progress in this browser?')){state.complete=[];state.notes={};state.entry=null;state.lessonSteps={};state.week=0;persist();journal();toast('Your demo data has been cleared.');}break;}});
document.addEventListener('input',e=>{if(e.target.id==='reflection'){state.notes[state.lessonDay]=e.target.value;persist();}});
$('#checkin-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.entry={wakes:Number(f.get('wakes')),awake:Number(f.get('awake')),hours:Number(f.get('hours')),rested:f.get('rested'),date:new Date().toISOString()};persist();$('#checkin').close();location.hash==='#journal'?journal():today();toast('Your morning check-in is saved in this browser.');});
$('#checkin .close').addEventListener('click',()=>$('#checkin').close());
$('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();});
function getSleepProfile(){const a=state.answers,scores=[0,0,0,0],evidence=[[],[],[],[]];const add=(i,n,t)=>{scores[i]+=n;if(t&&!evidence[i].includes(t))evidence[i].push(t);};if(a[5]===0)add(0,3,'Thoughts or to-do lists take over when you wake.');if(a[6]>=2)add(0,2,'Your mind often feels busy before bed.');if(a[9]===0)add(0,2,'Your evening often ends with work or planning.');if(a[5]===1)add(1,3,'You worry about not getting enough sleep.');if(a[7]===0)add(1,2,'You check the time and count the hours left.');if(a[8]>=2)add(2,3,'Your sleep routine changes substantially.');if(a[9]===3)add(2,2,'Your last half-hour before bed varies.');if(a[7]===1)add(2,1,'You return to your phone or work after waking.');if(a[5]===2)add(3,4,'Light, sound, temperature, or comfort disrupts you.');const order=scores.map((score,i)=>({score,i})).sort((x,y)=>y.score-x.score);const profiles=[{name:'The midnight overthinker',factor:'A busy mind at night',practice:'Close the tabs in your mind',day:8,why:'Give unfinished thoughts a place to land earlier in the evening.'},{name:'The clock watcher',factor:'Pressure around sleep',practice:'Make room for a difficult night',day:23,why:'Build a kinder response to an awake moment, with less pressure to solve the night.'},{name:'The shifting rhythm',factor:'An uneven routine',practice:'Meet your morning',day:15,why:'Choose one realistic morning cue before trying to change your whole routine.'},{name:'The sensitive sleep space',factor:'Your bedroom environment',practice:'A bedroom that feels restful',day:18,why:'Start with one small, practical comfort adjustment.'}];const top=order[0],known=top.score>0;return{...(known?profiles[top.i]:{name:'Your pattern is still unfolding',factor:'A pattern to explore',practice:'Meet your sleep diary',day:2,why:'A short morning estimate can help you notice what varies between nights.'}),evidence:known?evidence[top.i]:['Your answers do not point clearly to one factor. A morning diary is a useful place to start.'],secondary:known&&order[1].score>0?profiles[order[1].i].factor:null,night:[2,3].includes(a[2]),longTerm:a[1]>=2,goal:quizQuestions[0].options[a[0]]||'Understand my nights',format:quizQuestions[11].options[a[11]]||'A small daily practice'};}
window.addEventListener('hashchange',render);render();
